<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, CalendarClock, Check, Clock3, Eye, Package, Power, QrCode, RefreshCw, Save, ShieldCheck, Users } from 'lucide-vue-next'
import { fetchManagement, saveSchedule, type AuditItem, type ManagementOverview } from '../services/management'

const data=ref<ManagementOverview|null>(null),loading=ref(true),saving=ref(false),error=ref(''),saved=ref(false)
const start=ref(''),end=ref(''),frozenUntil=ref(''),status=ref<'active'|'frozen'>('active')
const maxView=computed(()=>Math.max(1,...(data.value?.dailyViews.map(x=>x.count)||[1])))
const actionNames:Record<string,string>={login_success:'Başarılı giriş',login_failed:'Başarısız giriş',product_created:'Ürün oluşturuldu',product_updated:'Ürün güncellendi',product_deleted:'Ürün silindi',products_cleared:'Ürünler temizlendi',category_created:'Kategori oluşturuldu',category_deleted:'Kategori silindi',settings_updated:'Menü ayarları değişti',schedule_updated:'Zamanlama güncellendi'}
const toInput=(value?:string|null)=>value?new Date(value).toISOString().slice(0,16):''
const formatDate=(value:string)=>new Intl.DateTimeFormat('tr-TR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))
const day=(value:string)=>new Intl.DateTimeFormat('tr-TR',{weekday:'short'}).format(new Date(`${value}T12:00:00`))
async function load(){loading.value=true;error.value='';try{data.value=await fetchManagement();const a=data.value.account;start.value=toInput(a.licenseStart);end.value=toInput(a.licenseEnd);frozenUntil.value=toInput(a.frozenUntil);status.value=a.status||'active'}catch(e){error.value=e instanceof Error?e.message:'Veriler alınamadı'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{await saveSchedule({licenseStart:new Date(start.value).toISOString(),licenseEnd:new Date(end.value).toISOString(),status:status.value,frozenUntil:status.value==='frozen'&&frozenUntil.value?new Date(frozenUntil.value).toISOString():null});saved.value=true;await load();setTimeout(()=>saved.value=false,1800)}catch(e){error.value=e instanceof Error?e.message:'Kaydedilemedi'}finally{saving.value=false}}
const logIcon=(item:AuditItem)=>item.action.includes('login')?Users:item.action.includes('schedule')?CalendarClock:item.action.includes('product')?Package:Activity
onMounted(load)
</script>

<template><div class="management-page">
  <header class="management-hero"><div><span>SİSTEM KONTROL MERKEZİ</span><h2>Tüm hareketler tek ekranda</h2><p>QR trafiğini, kullanıcı işlemlerini ve yayın zamanlamasını gerçek zamanlı yönetin.</p></div><button @click="load"><RefreshCw :size="17"/> Yenile</button></header>
  <p v-if="error" class="manage-error">{{error}}</p><div v-if="loading" class="manage-loading">Yönetim verileri hazırlanıyor...</div>
  <template v-else-if="data">
    <section class="control-strip"><div><i :class="status"></i><span>SİSTEM DURUMU</span><strong>{{status==='active'?'Yayında':'Donduruldu'}}</strong></div><div><span>İŞLETME</span><strong>{{data.account.company}}</strong><small>{{data.account.email}}</small></div><div><span>QR ADRESİ</span><strong>/menu/{{data.account.slug}}</strong><small>Kalıcı menü bağlantısı</small></div><ShieldCheck :size="30"/></section>
    <section class="metric-grid"><article><span class="metric-icon orange"><Eye :size="20"/></span><div><small>Toplam QR görüntüleme</small><strong>{{data.metrics.totalViews.toLocaleString('tr-TR')}}</strong><p>Veritabanında kalıcı</p></div></article><article><span class="metric-icon violet"><Package :size="20"/></span><div><small>Menü ürünleri</small><strong>{{data.metrics.products}}</strong><p>Toplam kayıt</p></div></article><article><span class="metric-icon green"><Users :size="20"/></span><div><small>Oturumlar</small><strong>{{data.metrics.sessions}}</strong><p>Oluşturulan girişler</p></div></article><article><span class="metric-icon blue"><Clock3 :size="20"/></span><div><small>Kalan lisans</small><strong>{{data.account.licenseDaysRemaining}}</strong><p>gün</p></div></article></section>
    <div class="management-grid"><section class="management-card chart-card"><header><div><span>QR ANALİTİĞİ</span><h3>Son 7 günlük trafik</h3></div><QrCode :size="22"/></header><div class="bar-chart"><div v-for="item in data.dailyViews" :key="item.date"><b>{{item.count}}</b><i :style="{height:`${Math.max(5,item.count/maxView*100)}%`}"></i><small>{{day(item.date)}}</small></div></div></section>
    <section class="management-card schedule-card"><header><div><span>ZAMANLANDIRMA</span><h3>Lisans ve yayın kontrolü</h3></div><CalendarClock :size="22"/></header><form @submit.prevent="save"><div class="date-grid"><label>Başlangıç<input v-model="start" type="datetime-local" required/></label><label>Bitiş<input v-model="end" type="datetime-local" required/></label></div><div class="status-picker"><button type="button" :class="{selected:status==='active'}" @click="status='active'"><Check :size="17"/><span><b>Aktif</b><small>QR menü yayınlansın</small></span></button><button type="button" :class="{selected:status==='frozen'}" @click="status='frozen'"><Power :size="17"/><span><b>Dondur</b><small>QR erişimini kapat</small></span></button></div><label v-if="status==='frozen'" class="freeze-date">Otomatik açılma zamanı <input v-model="frozenUntil" type="datetime-local"/><small>Boş bırakırsanız siz açana kadar donuk kalır.</small></label><button class="schedule-save" :disabled="saving"><Check v-if="saved" :size="17"/><Save v-else :size="17"/>{{saved?'Kaydedildi':saving?'Kaydediliyor...':'Zamanlamayı kaydet'}}</button></form></section></div>
    <section class="management-card activity-card"><header><div><span>DENETİM KAYITLARI</span><h3>Kim, ne zaman, ne yaptı?</h3></div><b>{{data.logs.length}} son işlem</b></header><div class="activity-table"><div class="activity-head"><span>İşlem</span><span>Detay</span><span>IP adresi</span><span>Zaman</span></div><div v-for="item in data.logs" :key="item.id" class="activity-row"><span class="action"><i><component :is="logIcon(item)" :size="15"/></i><b>{{actionNames[item.action]||item.action}}</b></span><span>{{item.detail||'—'}}</span><code>{{item.ip||'Yerel'}}</code><time>{{formatDate(item.createdAt)}}</time></div><div v-if="!data.logs.length" class="empty-log">Henüz kayıtlı işlem yok. Yeni hareketler burada kalıcı olarak görünecek.</div></div></section>
  </template>
</div></template>

<style scoped>
.management-page{max-width:1450px;margin:auto}.management-hero{display:flex;justify-content:space-between;align-items:end;margin-bottom:22px}.management-hero>div>span,.management-card header span{font-size:9px;letter-spacing:1.7px;color:var(--orange);font-weight:800}.management-hero h2{font-size:32px;margin:7px 0}.management-hero p{color:var(--muted);font-size:12px;margin:0}.management-hero>button{border:1px solid var(--line);background:#fff;height:42px;border-radius:11px;padding:0 15px;display:flex;align-items:center;gap:8px;font-size:11px;font-weight:700}.manage-error{padding:12px;background:#fff0ed;color:#bd493b;border-radius:10px}.manage-loading{padding:100px;text-align:center;color:var(--muted)}.control-strip{background:linear-gradient(120deg,#161c19,#26312c);color:#fff;border-radius:17px;padding:19px 23px;display:grid;grid-template-columns:220px 1fr 1fr auto;align-items:center;gap:25px;margin-bottom:16px}.control-strip>div{position:relative}.control-strip i{display:inline-block;width:9px;height:9px;border-radius:50%;background:#52d99a;box-shadow:0 0 0 5px #52d99a18;margin-right:9px}.control-strip i.frozen{background:#f07a45;box-shadow:0 0 0 5px #f07a4518}.control-strip span,.control-strip small{display:block;font-size:8px;color:#99a79f;letter-spacing:1px}.control-strip>div:first-child span{display:inline}.control-strip strong{display:block;font-size:13px;margin-top:6px}.control-strip svg{color:#65dca5}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}.metric-grid article{background:#fff;border:1px solid var(--line);border-radius:15px;padding:19px;display:flex;gap:13px;align-items:center}.metric-icon{width:42px;height:42px;border-radius:12px;display:grid;place-items:center}.metric-icon.orange{background:#fff0e9;color:#e36a35}.metric-icon.violet{background:#f1edff;color:#7555c7}.metric-icon.green{background:#e9f8f1;color:#159465}.metric-icon.blue{background:#eaf4fb;color:#3979a9}.metric-grid small,.metric-grid p{font-size:9px;color:var(--muted);margin:0}.metric-grid strong{display:block;font-size:25px;margin:3px 0}.management-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:16px;margin-bottom:16px}.management-card{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 5px 22px #20252209;overflow:hidden}.management-card>header{padding:20px 22px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.management-card h3{font-size:16px;margin:5px 0 0}.management-card header svg{color:var(--orange)}.bar-chart{height:245px;padding:38px 30px 24px;display:flex;align-items:end;gap:14px;background:repeating-linear-gradient(to top,#f1f3f0 0,#f1f3f0 1px,transparent 1px,transparent 48px)}.bar-chart>div{height:100%;flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;gap:7px}.bar-chart i{width:min(38px,75%);min-height:5px;background:linear-gradient(#fa9a6b,#e86e35);border-radius:8px 8px 3px 3px}.bar-chart b{font-size:9px}.bar-chart small{font-size:9px;color:var(--muted);text-transform:capitalize}.schedule-card form{padding:20px 22px}.date-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px}.schedule-card label{font-size:10px;font-weight:700;color:#5f6963}.schedule-card input{display:block;width:100%;height:42px;border:1px solid var(--line);border-radius:10px;padding:0 11px;margin-top:7px;font:inherit;color:var(--ink)}.status-picker{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:17px 0}.status-picker button{border:1px solid var(--line);border-radius:11px;background:#fff;padding:12px;display:flex;text-align:left;gap:9px;color:#8a938d}.status-picker button.selected{border-color:var(--orange);background:#fff7f2;color:var(--orange);box-shadow:0 0 0 2px #e86e3512}.status-picker b,.status-picker small{display:block}.status-picker b{font-size:11px;color:var(--ink)}.status-picker small{font-size:8px;margin-top:3px}.freeze-date small{display:block;font-size:8px;color:var(--muted);margin-top:5px}.schedule-save{height:42px;width:100%;border:0;border-radius:10px;background:#202522;color:#fff;display:flex;justify-content:center;align-items:center;gap:8px;font-size:11px;font-weight:700;margin-top:17px}.activity-card>header>b{font-size:9px;color:#168e64;background:#eaf8f1;padding:6px 9px;border-radius:8px}.activity-table{overflow-x:auto}.activity-head,.activity-row{min-width:760px;display:grid;grid-template-columns:1.15fr 1.5fr .7fr 1fr;align-items:center;gap:15px;padding:12px 22px}.activity-head{background:#f8f9f7;color:#949c97;font-size:8px;font-weight:800;letter-spacing:.8px}.activity-row{border-top:1px solid #eef0ed;font-size:10px;color:#68716b}.activity-row .action{display:flex;align-items:center;gap:9px}.activity-row .action i{width:30px;height:30px;border-radius:9px;background:#fff0e9;color:var(--orange);display:grid;place-items:center}.activity-row .action b{color:var(--ink)}.activity-row code{font-size:9px;background:#f3f4f2;padding:5px 7px;border-radius:6px;width:max-content}.activity-row time{white-space:nowrap}.empty-log{text-align:center;padding:45px;color:var(--muted);font-size:11px}
@media(max-width:1000px){.metric-grid{grid-template-columns:repeat(2,1fr)}.management-grid{grid-template-columns:1fr}.control-strip{grid-template-columns:1fr 1fr}.control-strip>svg{display:none}}@media(max-width:650px){.management-hero{align-items:stretch;flex-direction:column;gap:15px}.management-hero>button{justify-content:center}.metric-grid{grid-template-columns:1fr}.control-strip{grid-template-columns:1fr}.date-grid{grid-template-columns:1fr}.status-picker{grid-template-columns:1fr}}
</style>
